def _branches(panel, z):
    from scipy.optimize import least_squares
    (u, v1, v2) = (np.asarray(panel[k], dtype=float) for k in ('u', 'v1', 'v2'))

    def odd(x, freq):
        q = x * freq
        return np.column_stack((_affine(x), q / (1.0 + np.abs(q))))

    def even(x, freq):
        return _affine(np.cos(x * freq))

    def project(feature, target, start, bounds):

        def linear(f):
            return np.linalg.lstsq(feature(u, f), target, rcond=1e-10)[0]

        def residual(f):
            return (feature(u, f) @ linear(f) - target).ravel()
        f = least_squares(residual, np.full(u.shape[1], start), bounds=bounds).x
        return feature(z, f) @ linear(f)
    return (project(odd, v1, 0.83, (0.2, 3.0)), project(even, v2, 2.4, (1.5, 3.2)))

def lib(x):
    from itertools import combinations
    from itertools import combinations_with_replacement
    d = {}
    a = list(x.T)

    def add(k, v):
        d[k] = v
    for k in range(2, 5):
        for ids in combinations_with_replacement(range(4), k):
            add(str(ids), np.prod(x[:, ids], axis=1))
    for (i, j) in combinations(range(4), 2):
        (u, v) = (a[i], a[j])
        add(f'rat{i}{j}', u * v / (1 + 0.5 * (u * u + v * v)))
    w = {str(i): u for (i, u) in enumerate(a)}
    for (i, j) in combinations(range(4), 2):
        for sgn in (1, -1):
            w[f'{i},{sgn * j:+}'] = a[i] + sgn * a[j]
    for (key, u) in w.items():
        for fr in (0.5, 1, 1.5, 2, 2.5, 3):
            for (nm, fn) in [('sin', np.sin), ('cos', np.cos), ('tanh', np.tanh), ('exp', lambda x: np.exp(-x * x)), ('sat', lambda x: x / (1 + abs(x))), ('atan', np.arctan)]:
                add(f'{nm}{fr}:{key}', fn(fr * u))
    return (list(d), np.column_stack(list(d.values())))

def pol(x, d):
    from itertools import combinations_with_replacement
    return np.column_stack([np.prod(x[:, i], axis=1) for k in range(d + 1) for i in combinations_with_replacement(range(4), k)])
